// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _test(uint256 a, uint256 b) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0 && b > 0);
        vm.assume(address(this).balance >= a + b);
        try c.Deposit{value: a}() {} catch { return; }
        try c.Deposit{value: b}() {} catch { return; }
        assertTrue(c.balances(address(this)) == a + b);
    }

    function testFuzz_test(uint256 a, uint256 b) public {
        _test(a, b);
    }

    receive() external payable {}

    fallback() external payable {}
}
